    }).round(2).sort_values('aircraft_movements', ascending=False).head(10)
    top_airports_movements.columns = ['total_movements', 'total_passengers', 'avg_delay']
    top_airports_movements = top_airports_movements.reset_index()

    # Delay statistics - top 5 airports with highest average delay
    delay_data = df.dropna(subset=['avg_delay_minutes']).groupby(['airport_code', 'airport_name']).agg({
        'avg_delay_minutes': 'mean'
    }).round(2).sort_values('avg_delay_minutes', ascending=False).head(5)
    airports_with_highest_avg_delay = delay_data.reset_index()
    airports_with_highest_avg_delay.columns = ['airport_code', 'airport_name', 'avg_delay_minutes']

    # Overall average delay across all airports and years
    overall_avg_delay = df.dropna(subset=['avg_delay_minutes'])['avg_delay_minutes'].mean()

    # Prepare output
    output = {
        "top_airports_by_passengers": [
            {
                "airport_code": row['airport_code'],
                "airport_name": row['airport_name'],
                "total_passengers": int(row['total_passengers'])
            }
            for _, row in top_airports_passengers.iterrows()
        ],
        "top_airports_by_movements": [
            {
                "airport_code": row['airport_code'],
                "airport_name": row['airport_name'],
                "total_movements": int(row['total_movements'])
            }
            for _, row in top_airports_movements.iterrows()
        ],
        "delay_statistics": {
            "airports_with_highest_avg_delay": [
                {
                    "airport_code": row['airport_code'],
                    "airport_name": row['airport_name'],
                    "avg_delay_minutes": float(row['avg_delay_minutes'])
                }
                for _, row in airports_with_highest_avg_delay.iterrows()
            ],
            "overall_avg_delay": round(float(overall_avg_delay), 2)
        },
        "yearly_trends": {
            "year": [
                {
                    "year": int(row['year']),
                    "total_passengers": int(row['total_passengers']),
                    "total_movements": int(row['total_movements']),
                    "avg_delay": float(row['avg_delay'])
                }
                for _, row in yearly_trends.iterrows()
            ]
        }
    }

    # Save to JSON
    with open('/app/analysis_results.json', 'w') as f:
        json.dump(output, f, indent=2)

    print("Analysis complete. Results saved to /app/analysis_results.json")
    return output

if __name__ == "__main__":
    main()
